import json
data = json.load(open('/workdir/normalized.json'))

# Check for duplicate flows (src_ip, dst_ip, protocol, action, timestamp)
flows = []
for record in data:
    key = (record['src_ip'], record['dst_ip'], record['protocol'], record['action'], record['timestamp'])
    if key in flows:
        print(f"Duplicate found: {key}")
    else:
        flows.append(key)

print(f"Total unique flows: {len(flows)}")
EOF"}
